DROP TABLE IF EXISTS `equipo_checklist_detalle`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `equipo_checklist_detalle` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `equipo_id` bigint(20) unsigned NOT NULL,
  `item_id` bigint(20) unsigned NOT NULL COMMENT 'ID de catalogo_checklist_items',
  `estatus` enum('OK','Falla','No Aplica','Presente') NOT NULL,
  `cantidad` int(10) unsigned NOT NULL DEFAULT 1,
  `notas` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `equipo_item_unique` (`equipo_id`,`item_id`),
  KEY `item_id` (`item_id`),
  CONSTRAINT `equipo_checklist_detalle_ibfk_1` FOREIGN KEY (`equipo_id`) REFERENCES `equipos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `equipo_checklist_detalle_ibfk_2` FOREIGN KEY (`item_id`) REFERENCES `catalogo_checklist_items` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

