--
-- Table structure for table `equipo_eliminaciones`
--

DROP TABLE IF EXISTS `equipo_eliminaciones`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `equipo_eliminaciones` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `accion` varchar(40) NOT NULL DEFAULT 'ELIMINACION',
  `equipo_id_original` bigint(20) unsigned DEFAULT NULL,
  `numero_serie` varchar(255) NOT NULL,
  `codigo` varchar(255) DEFAULT NULL,
  `tipo_equipo` varchar(255) DEFAULT NULL,
  `marca` varchar(255) DEFAULT NULL,
  `modelo` varchar(255) DEFAULT NULL,
  `user_id` bigint(20) unsigned NOT NULL,
  `motivo` varchar(255) NOT NULL,
  `snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`snapshot`)),
  `ip` varchar(45) DEFAULT NULL,
  `user_agent` varchar(500) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `equipo_eliminaciones_user_id_foreign` (`user_id`),
  KEY `equipo_eliminaciones_numero_serie_index` (`numero_serie`),
  KEY `equipo_eliminaciones_codigo_index` (`codigo`),
  KEY `equipo_eliminaciones_tipo_equipo_index` (`tipo_equipo`),
  KEY `equipo_eliminaciones_accion_index` (`accion`),
  KEY `equipo_eliminaciones_equipo_id_original_index` (`equipo_id_original`),
  CONSTRAINT `equipo_eliminaciones_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

