DROP TABLE IF EXISTS `equipo_estancias`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `equipo_estancias` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `equipo_id` bigint(20) unsigned NOT NULL,
  `almacen_id` bigint(20) unsigned NOT NULL,
  `inicio_at` datetime NOT NULL,
  `fin_at` datetime DEFAULT NULL,
  `abierto_por` bigint(20) unsigned DEFAULT NULL,
  `cerrado_por` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `equipo_estancias_abierto_por_foreign` (`abierto_por`),
  KEY `equipo_estancias_cerrado_por_foreign` (`cerrado_por`),
  KEY `equipo_estancias_equipo_id_fin_at_index` (`equipo_id`,`fin_at`),
  KEY `equipo_estancias_almacen_id_inicio_at_index` (`almacen_id`,`inicio_at`),
  CONSTRAINT `equipo_estancias_abierto_por_foreign` FOREIGN KEY (`abierto_por`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `equipo_estancias_almacen_id_foreign` FOREIGN KEY (`almacen_id`) REFERENCES `almacenes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `equipo_estancias_cerrado_por_foreign` FOREIGN KEY (`cerrado_por`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `equipo_estancias_equipo_id_foreign` FOREIGN KEY (`equipo_id`) REFERENCES `equipos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
