DROP TABLE IF EXISTS `equipo_movimientos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `equipo_movimientos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `equipo_id` bigint(20) unsigned NOT NULL,
  `tipo` enum('ALTA_LOTE','MOVER_ALMACEN','ASIGNAR_TECNICO','FINALIZAR_TECNICO','VENTA','BAJA','AJUSTE') NOT NULL,
  `desde_almacen_id` bigint(20) unsigned DEFAULT NULL,
  `hacia_almacen_id` bigint(20) unsigned DEFAULT NULL,
  `ref_type` varchar(120) DEFAULT NULL,
  `ref_id` bigint(20) unsigned DEFAULT NULL,
  `motivo` text DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `ip` varchar(45) DEFAULT NULL,
  `user_agent` varchar(255) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `equipo_movimientos_desde_almacen_id_foreign` (`desde_almacen_id`),
  KEY `equipo_movimientos_hacia_almacen_id_foreign` (`hacia_almacen_id`),
  KEY `equipo_movimientos_created_by_foreign` (`created_by`),
  KEY `equipo_movimientos_equipo_id_created_at_index` (`equipo_id`,`created_at`),
  KEY `equipo_movimientos_tipo_created_at_index` (`tipo`,`created_at`),
  KEY `equipo_movimientos_ref_type_ref_id_index` (`ref_type`,`ref_id`),
  CONSTRAINT `equipo_movimientos_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `equipo_movimientos_desde_almacen_id_foreign` FOREIGN KEY (`desde_almacen_id`) REFERENCES `almacenes` (`id`) ON DELETE SET NULL,
  CONSTRAINT `equipo_movimientos_equipo_id_foreign` FOREIGN KEY (`equipo_id`) REFERENCES `equipos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `equipo_movimientos_hacia_almacen_id_foreign` FOREIGN KEY (`hacia_almacen_id`) REFERENCES `almacenes` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
