  `marca` varchar(100) DEFAULT NULL,
  `modelo` varchar(255) NOT NULL,
  `tipo_equipo` varchar(100) DEFAULT NULL,
  `tiene_grafica_integrada` tinyint(1) NOT NULL DEFAULT 0,
