  `puertos_usb_31` varchar(50) DEFAULT NULL,
  `puertos_usb_32` varchar(50) DEFAULT NULL,
  `puertos_usb_c` varchar(50) DEFAULT NULL,
  `lectores_sd` varchar(50) DEFAULT NULL,
  `lectores_microsd` varchar(50) DEFAULT NULL,
  `lectores_sc` varchar(50) DEFAULT NULL,
  `lectores_esata` varchar(50) DEFAULT NULL,
  `lectores_sim` varchar(50) DEFAULT NULL,
  `lectores_otro` varchar(255) DEFAULT NULL,
  `bateria_tiene` tinyint(1) NOT NULL DEFAULT 1,
  `teclado_idioma` varchar(50) DEFAULT 'N/A',
  `notas_generales` text DEFAULT NULL,
  `detalles_esteticos` text DEFAULT NULL,
  `detalles_funcionamiento` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `equipos_numero_serie_unique` (`numero_serie`),
  KEY `equipos_estatus_general_index` (`estatus_general`),
  KEY `registrado_por_user_id` (`registrado_por_user_id`),
  KEY `proveedor_id` (`proveedor_id`),
  KEY `lote_modelo_id` (`lote_modelo_id`),
  KEY `idx_equipos_gpu_flags` (`tiene_grafica_integrada`,`tiene_grafica_dedicada`),
