  CONSTRAINT `equipos_ibfk_1` FOREIGN KEY (`registrado_por_user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `equipos_ibfk_2` FOREIGN KEY (`proveedor_id`) REFERENCES `proveedores` (`id`),
  CONSTRAINT `equipos_ibfk_3` FOREIGN KEY (`lote_modelo_id`) REFERENCES `lote_modelos_recibidos` (`id`),
  CONSTRAINT `equipos_sucursal_id_foreign` FOREIGN KEY (`sucursal_id`) REFERENCES `sucursales` (`id`) ON DELETE SET NULL
