--
-- Table structure for table `garantias_proveedor`
--

DROP TABLE IF EXISTS `garantias_proveedor`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `garantias_proveedor` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `equipo_id` bigint(20) unsigned NOT NULL,
  `estatus_garantia` enum('Pendiente de Envío','Enviada','Resuelta','Rechazada') NOT NULL DEFAULT 'Pendiente de Envío',
  `fecha_envio` date DEFAULT NULL,
  `fecha_resolucion` date DEFAULT NULL,
  `notas` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `garantias_equipo_id_unique` (`equipo_id`),
  CONSTRAINT `garantias_proveedor_ibfk_1` FOREIGN KEY (`equipo_id`) REFERENCES `equipos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
