  CONSTRAINT `inventario_piezas_deshueso_ibfk_1` FOREIGN KEY (`pieza_id`) REFERENCES `catalogo_piezas` (`id`),
  CONSTRAINT `inventario_piezas_deshueso_ibfk_2` FOREIGN KEY (`equipo_origen_id`) REFERENCES `equipos` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
